const drEvGrantTasks=[["นัดพี่เวลและ 24CARFIX เพื่อกำหนดความร่วมมือ EV Platform", "สรุปเป้าหมายร่วม กลุ่มผู้ใช้ ปัญหาที่จะแก้ ขอบเขตแพลตฟอร์ม และบทบาทของแต่ละฝ่าย ยังเป็นข้อเสนอความร่วมมือ ไม่ใช่ข้อตกลงที่ยืนยันแล้ว", "high"], ["ตรวจประกาศ NIA และยืนยันกำหนดรับสมัครทุนรอบ 1/2570", "ตรวจสาขา Next-Generation Automotive เกณฑ์ เอกสาร ขั้นตอนและเวลาปิดรับกับ NIA โดยตรง ข้อความที่ได้รับระบุเปิด 16 ตุลาคม–15 ธันวาคม 2569\nรายละเอียด https://fininno.nia.or.th/manage_service/mandatory/\nวิดีโอ https://moocs.nia.or.th/course/thematic", "high"], ["ตรวจคุณสมบัตินิติบุคคลและเลือกผู้ยื่นโครงการ", "ตรวจทะเบียนนิติบุคคล สัดส่วนผู้ถือหุ้นไทยอย่างน้อย 51% ประสบการณ์ในอุตสาหกรรมของนิติบุคคลหรือกรรมการบริหารอย่างน้อย 3 ปี และความพร้อมของ Business Model / Business Plan ตามข้อความที่ได้รับ ยืนยันเกณฑ์จริงก่อนเลือกผู้ยื่น", "high"], ["ตกลงสิทธิ Core Technology / IP ระหว่าง DR.EV และ 24CARFIX", "ระบุเจ้าของเทคโนโลยีหลัก หลักฐานกรรมสิทธิ์หรือ Licensing ที่ผู้ยื่นใช้ได้ รวมถึงสิทธิในซอฟต์แวร์ ข้อมูล รายได้ และบทบาทคู่ร่วมโครงการ ให้ผู้เชี่ยวชาญตรวจข้อตกลงก่อนลงนาม", "normal"], ["เลือกกลไกทุนที่เหมาะกับระยะพัฒนา EV Platform", "เปรียบเทียบตามประกาศจริง ไม่ถือว่าได้รับทุนหรือรวมทุกวงเงินได้อัตโนมัติ\nThematic: ไม่เกิน 75%, 5 ล้านบาท, 3 ปี\nMIND: ไม่เกิน 50%, 1 ล้านบาท, 1 ปี\nStandard Testing: ไม่เกิน 50%, 1.5 ล้านบาท, 1 ปี\nMarket Expansion: กลุ่มลูกค้ารัฐ 100% / เอกชน 50%, ไม่เกิน 2 ล้านบาท, 1 ปี\nZero Loan Interest: สูงสุด 100% ของดอกเบี้ย ไม่ใช่เงินต้น ไม่เกิน 5 ล้านบาท, 3 ปี", "normal"], ["จัดทำ Business Model และแผนธุรกิจ EV Platform", "สรุปคุณค่าที่แตกต่าง กลุ่มลูกค้า รายได้ ต้นทุน ช่องทางตลาด คู่แข่ง และประโยชน์ต่อระบบนิเวศ EV ของประเทศ แยกเป้าหมายที่คาดหวังจากผลลัพธ์ที่มีหลักฐาน", "normal"], ["จัดทำแผนพัฒนา โครงการนำร่อง และตัวชี้วัด", "แบ่งระยะพัฒนาและทดสอบ กำหนดกลุ่มลูกค้า/พันธมิตรนำร่อง ผลส่งมอบ ผู้รับผิดชอบ ระยะเวลา KPI และแผนบริหารความเสี่ยง ให้สอดคล้องกลไกทุนที่เลือก", "normal"], ["จัดทำงบประมาณและยืนยันเงินสมทบ", "แยกรายการค่าใช้จ่ายที่ขอทุนได้/ไม่ได้ ขอใบเสนอราคาตามเกณฑ์ และระบุแหล่งเงินสมทบ\nตัวอย่างคำนวณเท่านั้น: ถ้าขอ Thematic เต็ม 5 ล้านบาทที่อัตรา 75% มูลค่าโครงการต้องอย่างน้อยประมาณ 6.67 ล้านบาท เงินสมทบประมาณ 1.67 ล้านบาท ทั้งนี้ต้องผ่านเกณฑ์และการพิจารณาจริง", "normal"], ["รวบรวมเอกสารและตรวจความพร้อมระบบ MIS NIA", "ตรวจเช็กลิสต์จริง เตรียมเอกสารนิติบุคคล ผู้ถือหุ้น ประวัติผลงาน หลักฐานเทคโนโลยี/สิทธิ แผนธุรกิจ แผนโครงการ และงบประมาณตามที่กำหนด\nตรวจบัญชีและสิทธิผู้ยื่นที่ https://mis.nia.or.th/ ไม่บันทึกรหัสผ่านลงรายละเอียดงาน", "normal"], ["ตรวจทานและยื่นข้อเสนอทุน NIA ก่อนปิดรับ", "ให้พี่เวลและผู้มีอำนาจตรวจชื่อผู้ยื่น ขอบเขต งบประมาณ สิทธิและเอกสาร ยื่นผ่าน https://mis.nia.or.th/ และเก็บเลขอ้างอิง/หลักฐานรับเรื่อง\nกำหนดปิดรับตามข้อความที่ได้รับ: 15 ธันวาคม 2569 ต้องยืนยันเวลาปิดรับกับประกาศจริงและเผื่อเวลายื่น", "high"], ["ติดตามผลยื่นทุนและเตรียมตอบข้อซักถาม", "หลังยื่นแล้ว บันทึกเลขคำขอ ช่องทางติดต่อ วันนัดหมาย และรายการข้อมูลเพิ่มเติมที่ NIA ขอ ตั้งวันติดตามตามกำหนดจริง ไม่ถือว่ายื่นหรืออนุมัติแล้ว", "normal"]];
if(storageOK){try{const marker='dayflow.setup.drev-nia2570.v1';if(!localStorage.getItem(marker)){const additions=drEvGrantTasks.map(([title,detail,priority],i)=>({id:'d7e02570-0000-4000-8000-'+String(i+1).padStart(12,'0'),title,notes:'DR.EV × 24CARFIX | NIA ปีงบประมาณ 2570\nข้อมูลตั้งต้นจากข้อความที่พี่เวลส่ง ยังไม่ยืนยันประกาศทางการ\n'+detail,project:'DR.EV',requestedBy:'พี่เวล',date:localDate(),status:'pending',priority,completed:null})).filter(t=>!tasks.some(existing=>existing.id===t.id));const merged=[...tasks,...additions];localStorage.setItem(key,JSON.stringify(merged));tasks=merged;localStorage.setItem(marker,'1');}}catch{toast('เพิ่มรายการทุนยังไม่สำเร็จ กรุณาสำรองข้อมูลและตรวจพื้นที่จัดเก็บ');}}

const policeProposalTask={"id": "d3110071-0051-4021-8000-000000000001", "title": "จัดทำข้อเสนอระบบสนับสนุนงานตำรวจ ปี 2571 จำนวน 3 แผน พร้อมภาพประกอบ", "project": "Delivery Drone", "requestedBy": "พี่นัท", "priority": "high", "status": "pending", "completed": null, "notes": "สรุปคำสั่งพี่นัท\nจัดทำแนวคิดข้อเสนอ 3 ทางเลือกสำหรับงานตำรวจส่วนกลางในกรุงเทพฯ และปริมณฑล ปี 2571 ให้ตอบโจทย์ภารกิจจริง เป็นระบบภาพรวมที่อาจมีทั้งโดรนและเทคโนโลยีอื่น ไม่จำกัดเฉพาะโดรน พร้อมทำภาพประกอบแต่ละแผนเพื่อใช้เสนอ\n\nกรอบงบประมาณเบื้องต้นจากพี่นัท\n• งบเสนอรวมประมาณ 51,000,000 บาท\n• ต้นทุนเป้าหมายฝั่งเราประมาณ 21,000,000 บาท\n• เป็นกรอบประมาณการ ยังไม่ได้รับอนุมัติ ส่วนต่างไม่ใช่กำไรสุทธิ ต้องแจกแจงภาษี การติดตั้ง บุคลากร บำรุงรักษา และความเสี่ยง\n\nสิ่งที่ต้องทำ / ผลส่งมอบ\n1. ยืนยันหน่วยงานเจ้าของเรื่องและความหมายของ “ตำรวจสกบ.” รวมถึงผู้รับข้อเสนอ กลุ่มผู้ใช้ พื้นที่นำร่อง และกรอบจัดซื้อหรือทุนที่เกี่ยวข้อง\n2. สรุปปัญหาและความต้องการของตำรวจส่วนกลางในกรุงเทพฯ–ปริมณฑล เพื่อระบุว่าระบบจะตอบโจทย์ด้านใดและวัดผลอย่างไร\n3. พัฒนาแนวคิดระบบ 3 แผนที่แตกต่างกัน แต่ละแผนระบุปัญหา ขอบเขตงาน องค์ประกอบโดรน/ระบบอื่น วิธีใช้งาน ประโยชน์ และ KPI\n4. จัดทำภาพแนวคิดหรือแผนผังการทำงานของแต่ละแผน พร้อมคำอธิบายภาษาไทย (ยังไม่ได้สร้างภาพ)\n5. แจกแจงงบเสนอและต้นทุนของแต่ละทางเลือกเทียบกรอบ 51/21 ล้านบาท ตรวจความเป็นไปได้และค่าใช้จ่ายตลอดอายุระบบ\n6. เปรียบเทียบ 3 แผนด้านความเหมาะสม ความพร้อม ระยะเวลา ความเสี่ยง การดูแลต่อเนื่อง และกฎหมาย/การคุ้มครองข้อมูลที่เกี่ยวข้อง\n7. สรุปข้อเสนอและภาพให้พี่นัทพิจารณา ก่อนยืนยันแผนและช่องทางยื่น\n\nข้อมูลอ้างอิงจากภาพที่ส่ง (ต้องตรวจสอบความเกี่ยวข้อง)\nภาพเป็นประกาศ วท.กห. กรมวิทยาศาสตร์และเทคโนโลยีกลาโหม เปิดรับ Pre-Proposal ทุนวิจัยด้านความมั่นคงของประเทศ ปีงบประมาณ 2571 ไม่ใช่หลักฐานยืนยันว่าเป็นงบตำรวจ 51 ล้านบาท\nกรอบในภาพ: งานวิจัยขั้นแนวหน้าเพื่อเตรียมพร้อมอนาคต และการเสริมสร้างความมั่นคง/การนำผลวิจัยไปใช้ประโยชน์\nวันปิดรับตามภาพ: 30 ตุลาคม 2569 ต้องยืนยันประกาศฉบับเต็ม คุณสมบัติผู้ยื่น หน่วยงานร่วม และว่าข้อเสนอตำรวจนี้ใช้ช่องทางดังกล่าวจริงหรือไม่\nยังไม่ทราบวันส่งให้พี่นัท ห้ามถือว่าวันปิดรับในภาพเป็นกำหนดส่งงานนี้โดยอัตโนมัติ"};
if(storageOK){try{const marker='dayflow.setup.delivery-police2571.v1';if(!localStorage.getItem(marker)){if(!tasks.some(t=>t.id===policeProposalTask.id)){const merged=[...tasks,{...policeProposalTask,date:localDate()}];localStorage.setItem(key,JSON.stringify(merged));tasks=merged;}localStorage.setItem(marker,'1');}}catch{toast('เพิ่มงานข้อเสนอตำรวจยังไม่สำเร็จ กรุณาตรวจพื้นที่จัดเก็บ');}}
